-- Capital Square model units from the sales team: 3D layouts and interiors per
-- unit type. The albums replace the old "Căn hộ mẫu" group of this project.
ON CONFLICT ("key") DO UPDATE SET "size_bytes" = EXCLUDED."size_bytes", "width" = EXCLUDED."width", "height" = EXCLUDED."height";

UPDATE "projects" SET
  "unit_types" = (
    SELECT jsonb_agg(
      CASE WHEN row->>'name' = 'Căn 3 phòng ngủ' AND NOT row ? 'image'
        THEN row || '{"image":"/images/projects/capital-square/layout-can-3pn.webp"}'::jsonb
        ELSE row END
      ORDER BY position)
    FROM jsonb_array_elements("unit_types") WITH ORDINALITY AS t(row, position)),
  "photos" = COALESCE((
      SELECT jsonb_agg(photo ORDER BY position)
      FROM jsonb_array_elements("photos") WITH ORDINALITY AS t(photo, position)
      WHERE photo->>'group' <> 'Căn hộ mẫu'
    ), '[]'::jsonb) || '[{"group":"Căn 1 phòng ngủ","image":"/images/projects/capital-square/layout-can-1pn.webp"},{"group":"Căn 1 phòng ngủ","image":"/images/projects/capital-square/mau/1pn-11.webp"},{"group":"Căn 1 phòng ngủ","image":"/images/projects/capital-square/mau/1pn-05.webp"},{"group":"Căn 1 phòng ngủ","image":"/images/projects/capital-square/mau/1pn-04.webp"},{"group":"Căn 1 phòng ngủ","image":"/images/projects/capital-square/mau/1pn-08.webp"},{"group":"Căn 1 phòng ngủ","image":"/images/projects/capital-square/mau/1pn-07.webp"},{"group":"Căn 1 phòng ngủ","image":"/images/projects/capital-square/mau/1pn-13.webp"},{"group":"Căn 1 phòng ngủ","image":"/images/projects/capital-square/mau/1pn-12.webp"},{"group":"Căn 1 phòng ngủ","image":"/images/projects/capital-square/mau/1pn-10.webp"},{"group":"Căn 2 phòng ngủ","image":"/images/projects/capital-square/layout-can-2pn.webp"},{"group":"Căn 2 phòng ngủ","image":"/images/projects/capital-square/mau/2pn-08.webp"},{"group":"Căn 2 phòng ngủ","image":"/images/projects/capital-square/mau/2pn-06.webp"},{"group":"Căn 2 phòng ngủ","image":"/images/projects/capital-square/mau/2pn-03.webp"},{"group":"Căn 2 phòng ngủ","image":"/images/projects/capital-square/mau/2pn-01.webp"},{"group":"Căn 2 phòng ngủ","image":"/images/projects/capital-square/mau/2pn-09.webp"},{"group":"Căn 2 phòng ngủ","image":"/images/projects/capital-square/mau/2pn-07.webp"},{"group":"Căn 2 phòng ngủ","image":"/images/projects/capital-square/mau/2pn-02.webp"},{"group":"Căn 2 phòng ngủ","image":"/images/projects/capital-square/mau/2pn-05.webp"},{"group":"Căn 2 phòng ngủ","image":"/images/projects/capital-square/mau/2pn-12.webp"},{"group":"Căn 3 phòng ngủ","image":"/images/projects/capital-square/layout-can-3pn.webp"},{"group":"Căn 3 phòng ngủ","image":"/images/projects/capital-square/mau/3pn-13.webp"},{"group":"Căn 3 phòng ngủ","image":"/images/projects/capital-square/mau/3pn-16.webp"},{"group":"Căn 3 phòng ngủ","image":"/images/projects/capital-square/mau/3pn-11.webp"},{"group":"Căn 3 phòng ngủ","image":"/images/projects/capital-square/mau/3pn-01.webp"},{"group":"Căn 3 phòng ngủ","image":"/images/projects/capital-square/mau/3pn-03.webp"},{"group":"Căn 3 phòng ngủ","image":"/images/projects/capital-square/mau/3pn-09.webp"},{"group":"Căn 3 phòng ngủ","image":"/images/projects/capital-square/mau/3pn-04.webp"},{"group":"Căn 3 phòng ngủ","image":"/images/projects/capital-square/mau/3pn-07.webp"},{"group":"Căn 3 phòng ngủ","image":"/images/projects/capital-square/mau/3pn-14.webp"},{"group":"Căn 3 phòng ngủ","image":"/images/projects/capital-square/mau/3pn-08.webp"},{"group":"Căn 3 phòng ngủ","image":"/images/projects/capital-square/mau/3pn-12.webp"},{"group":"Căn 3 phòng ngủ","image":"/images/projects/capital-square/mau/3pn-02.webp"},{"group":"Căn 3 phòng ngủ","image":"/images/projects/capital-square/mau/3pn-15.webp"},{"group":"Căn 3 phòng ngủ","image":"/images/projects/capital-square/mau/3pn-05.webp"}]'::jsonb
WHERE "slug" = 'capital-square' AND jsonb_array_length("unit_types") > 0;
